input.command:
F=".first-principles/analysis-20261009T035921Z.md"
for h in 57 70 82 97 111 124 141 153 208; do echo $h; done
# extract each chain's fenced block and count hop lines
sed -n '57,206p' "$F" | awk '
/^### C/{print "CHAIN:", $0}
/^```text$/{f=1;next}
/^```$/{f=0}
f && /^→/{print "  HOP:", $0}
'

F=".first-principles/analysis-20261009T035921Z.md"
sed -n '57,206p' "$F" | awk '
/^### C([0-9]+)/{match($0,/C[0-9]+/); cid=substr($0,RSTART,RLENGTH); next}
/^```text$/{f=1;next}
/^```$/{f=0}
f && /^→/{print cid"\t"$0}
' > /tmp/hops.tsv
wc -l /tmp/hops.tsv
head -5 /tmp/hops.tsv

F=".first-principles/analysis-20261009T035921Z.md"; R="${F%/*}/report-${F##*/analysis-}"; { printf '# '; cat <<'FP_EOF'
Northbrook Analytics Churn Root-Cause Diagnosis
FP_EOF
printf '\n*First-principles analysis · %s*\n\n' "$(date -u '+%-d %B %Y')"
printf '*Read with: [How to read this analysis]''(HOW-TO-READ.md) · [Working file]''(%s) · [All files]''(INDEX.md)*\n\n' "${F##*/}"; awk '
/^```/ { f = !f }
!f && /^## Appendix — process output$/ { exit }
!f && /^\*\*Disclosed:\*\*/ { skip = 1 }
skip && /^#/ { skip = 0 }
skip { if ($0 == "") skip = 0; next }
!f && /^\*\*Pre-check:\*\*/ { next }
!f && /^## Answer$/ { $0 = "## Executive Summary" }
!f && (/^#/ || /^\*\*/) && prev != "" { print "" }
{ print; prev = $0 }' "$F" | cat -s; } > "$R" && echo "$R"

R=".first-principles/report-20261009T035921Z.md"; B="${R##*/}"; B="${B%.md}"
TL=""; [ -s "${R%.md}-fig-trace.svg" ] && TL="![Evidence trace: ground truths, chains and the conclusion]""($B-fig-trace.svg)"
VL=""; [ -s "${R%.md}-fig-verdicts.svg" ] && VL="![Assumption verdict matrix: assumption types against verdicts]""($B-fig-verdicts.svg)"
awk -v t="$TL" -v v="$VL" '
  /^```/ { f = !f }
  !f && /^!\[.*-fig-(trace|verdicts)\.svg\)$/ { next }
  { print }
  !f && $0 == "## 2. Assumptions Table" && v != "" { print ""; print v; print "" }
  !f && $0 == "## 4. Derivation Chains" && t != "" { print ""; print t; print "" }
' "$R" | cat -s > "$R.tmp" && mv "$R.tmp" "$R"
rm -f "$R.tmp"
grep -n "fig-" "$R"
